      "cooldownMin(같은 알림을 다시 보내기까지의 간격, 기본 60분) · intervalSec(평가 주기, 기본 60초, 15초~1일) · suppressWindowMin(채널과 무관하게 같은 알림의 중복을 막는 창, 기본 5분)."
