    "writer": "설정 › 알림 화면에서 저장할 때와, 설정 › Security › 이상동작 탐지 화면에서 대량 VM 전원 꺼짐 규칙을 저장할 때 씁니다. 파일 전체를 원자적으로 다시 쓰고 권한은 0600 이며, 저장하면 평가 주기가 바로 다시 적용됩니다. 알림 엔진은 이 파일을 읽기만 하고, 지금 발생 중인 알림 상태는 따로 ‘alerts-state.json’ 에 남깁니다. 알림 엔진은 중앙과 엣지 양쪽에서 돌며, 각 포탈은 자기 파일을 씁니다.",
