    "writer": "설정 › User Control › 인증(AD) 화면에서 저장할 때만 씁니다. 관리자이면서 전체 범위 계정이고 설정 소유자(설정 화면 접근이 허용된 계정)여야 저장할 수 있습니다. 임시 파일에 쓴 뒤 바꿔치는 방식(원자적 쓰기)으로, 소유자만 읽을 수 있는 권한(0600)으로 저장합니다. 주기적으로 쓰는 일은 없습니다.",
