    "ifDeleted": "파일이 없으면 환경 변수 AD_ 로 시작하는 값으로 동작하고, 환경 변수도 없으면 AD 로그인이 꺼져 포탈 로컬 계정만 로그인할 수 있습니다. 파일이 손상되면 ‘auth.json.corrupt.<시각>’ 으로 보존하고 환경 변수 값으로 동작합니다. 포탈 백업(설정 › 포탈 백업)에 들어 있으므로 백업에서 되살릴 수 있습니다.",
