    "title": "베어메탈 사용률 엣지 배포 설정",
    "summary": "중앙(메인) 포탈의 ‘베어메탈 사용률’ 수집 설정을 모든 엣지(각 법인 현지에 설치된 수집 포탈)에 한 번에 내려보낼지, 그리고 어느 엣지를 빼 둘지를 기록하는 작은 설정 파일입니다. 예전에는 엣지 28곳을 하나씩 들어가 켜야 했는데, 이 배포를 켜면 엣지들이 다음 인출 때 중앙 설정을 받아 씁니다. 배포되는 실제 값(켜기·법인·주기·보존 등)은 이 파일이 아니라 중앙의 ‘bmusage-settings.json’ 에 있습니다.",
