    "writer": "특수 기능 › 베어메탈 사용률 › 설정 › ‘엣지에 배포’ 의 ‘이 설정을 모든 엣지에 배포(한 번에 켜기)’ 체크와 엣지별 ‘제외’ 체크가 씁니다(관리자 · 전체 범위, 감사 로그 기록). 저장할 때마다 파일 전체를 원자적으로 다시 쓰며 권한은 0600 입니다. 주기적으로 이 파일을 쓰는 폴러는 없습니다. 이 화면은 중앙에서만 보이므로 실제로는 중앙 포탈에만 생깁니다.",
