      "엣지 설정 배포: 엣지가 기본 10분마다(첫 인출은 기동 약 45초 뒤, ‘AGENT_BMUSAGE_CONFIG_PULL_MS’) 중앙에 물으면, 중앙이 이 파일을 보고 그 엣지에 설정을 줄지(배포 켬·제외 아님) 말지를 답합니다. 엣지는 받은 값을 ‘bmusage-central.json’ 에 사본으로 두고 로컬 설정 위에 겹쳐 씁니다.",
