    "ifDeleted": "파일이 없으면 ‘배포 꺼짐’ 으로 처리됩니다. 그러면 엣지들이 다음 인출(기본 10분 안)에서 ‘배포 꺼짐’ 답을 받아 받아 둔 사본을 지우고 각자 로컬 설정으로 돌아갑니다(코드 확인). 반대로 파일이 깨져 읽히지 않으면 원본을 ‘.corrupt.<시각>’ 으로 보존하고, 중앙은 엣지에 ‘설정을 읽지 못했다’(503)로 답해 엣지가 마지막 사본을 그대로 유지합니다. 이 상태는 관리자가 배포 설정을 다시 저장하거나 특수 기능 › 다빈치 서비스 점검의 설정 파일 항목에서 기본값으로 확정할 때까지 이어집니다. 설정 › 포탈 백업에 포함되므로 백업에서 복원할 수 있습니다.",
