    "growth": "노드 수(중앙 1 + 보고하는 엣지 수)에 비례합니다. 코드 주석의 계산으로는 중앙과 엣지 28곳의 원본 72시간이 약 117만 행이고, 1시간 요약은 노드당 약 8.6만 행(9개 지표 × 24시간 × 400일, 계산값)입니다.",
