    "ifDeleted": "지우면 지난 추이만 사라지고 현재 진단은 다음 측정부터 다시 채워집니다. 다음에 DB 를 열 때 빈 파일이 새로 만들어집니다. 지우는 방법: 서비스가 도는 중에 지우면 열린 파일에 계속 쓰기 때문에 디스크 공간이 돌아오지 않습니다. 서비스를 멈춘 뒤 같은 이름의 ‘-wal’·‘-shm’ 파일과 함께 지워야 합니다(일반적인 SQLite·리눅스 동작).",
