    "shrink": "줄일 필요가 없습니다.",
    "ifDeleted": "개별 토큰이 모두 사라져, 개별 토큰을 쓰던 엣지의 중앙 요청이 전부 거부(403)됩니다 — 인벤토리·스토리지 등의 push 와 설정 pull 이 멈춥니다. 공유 토큰(‘CENTRAL_TOKEN’)도 설정돼 있지 않으면 중앙 수신 기능 자체가 꺼진 것으로 응답합니다(404). 복구하려면 엣지마다 토큰을 다시 발급해 그 엣지의 ‘portal.env’ 에 넣어야 합니다. 설정 › 포탈 백업에 포함되므로 백업에서 복원하면 기존 토큰이 그대로 다시 통합니다. 포탈이 실행 중이면 메모리에 든 목록을 다음 사용 기록 때 다시 써서 파일이 되살아나므로, 효과를 보려면 서비스를 멈춘 뒤 지워야 합니다. 파일이 깨져 읽히지 않으면 ‘.corrupt.<시각>’ 으로 옮겨 두고 빈 목록으로 시작합니다.",
