    "writer": "폴더 사용량 스케줄러가 60초마다(환경 변수 DIRUSAGE_TICK_MS) 실행할 때가 된 대상을 찾아 에이전트에 ‘du-top’ 작업을 보내고, 이후 실행 때 결과를 거둬 상위 N개로 정리해 한 줄을 씁니다. 대상마다 기본 24시간 간격(1시간~30일), 상위 20개(1~200), 대상은 최대 50개, 작업 시한은 15분(환경 변수 DIRUSAGE_JOB_TIMEOUT_MS)입니다. 대상과 주기는 설정 › 폴더 사용량 리포트(‘dirusage.json’)에서 정하고, 메일은 설정 › 메일 발송 의 공용 설정으로 보냅니다.",
