    "writer": "관리자가 '설정 › GPU 사용량 수집 › GPU 게스트 수집' 에서 저장할 때 씁니다. 계정 이름이 바뀌면 전에 저장한 비밀번호를 이어받지 않고 버리며, 그 사실을 저장 결과로 알려 줍니다(다른 계정에 옛 비밀번호가 쓰이지 않게). 엣지 포탈에서는 중앙이 그 엣지 앞으로 지정한 설정을 엣지가 기본 60초마다(‘AGENT_INVENTORY_INTERVAL_MS’, 이 기능은 최소 30초, 시작 8초 뒤 첫 인출) 가져와 이 파일에 합쳐 씁니다. 중앙이 보낸 vCenter 의 VM 별 계정·IP 는 중앙 사본이 기준이라 중앙에서 지운 항목은 엣지에서도 지우고, 엣지가 직접 등록한 vCenter 설정은 그대로 둡니다. 내용이 바뀌지 않으면 파일을 다시 쓰지 않습니다.",
