    "ifDeleted": "지우면 GPU 게스트 수집이 기본값(꺼짐)으로 돌아가 게스트 GPU 사용률이 더 이상 갱신되지 않고, 이 계정을 빌려 쓰던 기능(실제 OS 확인·심층 검색·게스트 조사 작업 등)도 계정이 없어 동작하지 않습니다. 계정과 비밀번호를 다시 입력해야 합니다(포탈 백업이 있으면 그것으로 되돌릴 수 있습니다). 엣지라면 중앙이 지정해 둔 부분은 다음 인출 때 다시 내려옵니다. 파일이 깨져 읽을 수 없으면 원본을 ‘<파일명>.corrupt.<시각>’ 이름으로 따로 보존합니다.",
