    "ifDeleted": "등록된 커넥션 서버와 계정이 사라져, 라이선스 만료일 화면에서 Horizon 라이선스가 빠지고 Horizon 실시간 사용자 수집도 대상이 없어 멈춥니다(이미 쌓인 ‘horizon-sessions.db’ 이력은 남습니다). 설정 › 포탈 백업에 포함되므로 백업에서 복원할 수 있습니다. 파일이 깨져 읽히지 않으면 원본을 ‘.corrupt.<시각>’ 으로 보존하고 빈 목록으로 시작합니다.",
