      "vCenter 전력 포함 여부(‘power-settings.json’)를 바꾸는 화면과, 전력 이력을 지우는 관리 기능(‘/admin/idrac/power-purge’)을 부르는 화면은 찾지 못했습니다.",
      "'특수 기능 › 포탈 DB' 의 DB 저장 경로 이전 대상입니다. ‘IDRAC_DB_PATH’ 로 위치를 따로 정했다면 그 경로가 먼저입니다."
