    "writer": "설정 › 수집 서버 › iDRAC 서버 등록에서 관리자가 추가·수정·삭제하거나 CSV/JSON 가져오기·IP 일괄 추가를 할 때 씁니다. iDRAC 스캔(등록한 IP 대역을 훑어 iDRAC 을 찾는 기능 — 기본 6시간마다, ‘IDRAC_SCAN_INTERVAL_MS’)과 에이전트(엣지) 위임 스캔이 찾은 서버를 자동 등록할 때도 씁니다. 쓸 때마다 파일 전체를 원자적으로 다시 쓰고 권한은 0600 입니다. 수집기(iDRAC 폴러)는 이 파일을 읽기만 하며 전력은 기본 1분(‘IDRAC_POLL_INTERVAL_MS’), 인벤토리는 약 30분마다 다시 읽습니다. 중앙과 엣지 모두에 이 파일이 있고, 엣지 서버는 엣지 자신의 이 파일에 등록됩니다. 중앙은 엣지 서버를 이 파일에 복사하지 않고 엣지가 내보내는 목록(수집 서버 pull)으로 따로 받습니다.",
