    "ifDeleted": "등록된 서버와 계정이 모두 사라져 전력·온도·인벤토리 수집이 멈추고, 서버 분석·전력·온도·부품 장애 화면에서 그 서버들이 빠집니다. 전력 이력(‘idrac-power.db’)과 온도 추이(‘host-temp.db’)의 과거 값은 남지만 연결된 서버가 없어 화면에 나오지 않습니다. iDRAC 스캔 대역(‘idrac-scan-ranges.json’)이 설정돼 있으면 다음 스캔이 찾은 서버를 그 대역의 계정으로 다시 자동 등록하지만, 손으로 넣은 이름·ESXi 호스트 매핑·vCenter 지정은 돌아오지 않습니다. 설정 › 포탈 백업에 포함되므로 백업에서 복원할 수 있습니다. 파일이 깨져 읽히지 않으면 원본을 ‘.corrupt.<시각>’ 으로 보존하고 빈 목록으로 시작합니다.",
