    "writer": "IP 스캔 결과가 들어올 때마다 합쳐 씁니다. 출처는 두 가지입니다. 이 포탈이 직접 스캔한 결과('IP관리 › IP 스캔 설정' 의 주기, 기본 1시간, 60초~7일)와 엣지가 스캔해 중앙으로 보낸 결과입니다. 또 정리 작업이 스캔 직후와 10분마다 돌면서, 스캔 주기의 3배(최소 3시간) 동안 응답이 없던 IP 를 '응답 없음' 으로 바꿉니다. 변경은 메모리에 먼저 반영하고 1.5초 모아서(‘IPAM_WRITE_DEBOUNCE_MS’) 파일 전체를 새로 쓰며, 포탈이 종료될 때도 남은 변경을 마저 씁니다.",
