    "writer": "관리자가 '설정 › 수집 서버 › 지표 수집' 이나 '설정 › GPU 사용량 수집 › GPU 수집' 에서 저장할 때만 씁니다. 저장하면 지표 수집기가 새 주기로 바로 다시 맞춰집니다. 범위가 제한된 관리자 계정의 저장은 전체에 영향을 주는 설정이라 반영하지 않고 그 사실을 알려 줍니다.",
