    "writer": "설정 › NSX 관리 화면에서 매니저를 추가·수정·삭제할 때만 씁니다(관리자 + 전체 범위). 변경은 감사 로그에 ‘NSX Manager 추가/수정/삭제’ 로 남습니다. 수집기는 이 파일을 읽기만 하며, 매니저별 주기가 없으면 전역 주기(환경 변수 POLL_INTERVAL_MS, 기본 30초)마다 접속합니다. 수집 결과는 파일에 쓰지 않고 메모리에만 둡니다.",
