      "SQLite 를 WAL(쓰기 내용을 먼저 적어 두는 보조 파일) 방식으로 열어 ‘-wal’·‘-shm’ 파일이 함께 생깁니다. 크기는 세 파일을 합쳐 봐야 하며 '특수 기능 › 포탈 DB' 화면은 합친 크기를 보여 줍니다. 파일 권한은 0600(포탈 서비스 계정만 읽기·쓰기)입니다.",
