      "로그인 정책(loginPolicy): 비어 있으면 기본 방식(관리자·운영자는 OTP 만, 그 밖은 비밀번호와 OTP 혼용), otp_only(전원 OTP 만), otp_or_password(둘 중 하나), password_only(비밀번호만).",
