      "‘agents’ — 엣지 이름별로 따로 정한 주기(최대 200곳). 이름이 빈 칸인 항목은 중앙 자신(중앙이 직접 수집하는 장비)입니다. 엣지별 값이 공통 값을 덮습니다.",
      "항목은 넷이고 값은 밀리초입니다: ‘pollMs’(장비 수집 주기, 기본 1시간) · ‘pushMs’(중앙 전송 주기, 기본 5분) · ‘configPullMs’(중앙 설정 수신 주기, 기본 5분) · ‘areasMs’(PowerScale 쿼터·공유 같은 영역 전수 수집 주기, 기본 1시간).",
      "‘version’ — 파일 형식 번호(1)."
