      "설정 › 수집 서버 › 스토리지 수집 주기: 공통·엣지별 입력, 엣지마다 실제로 내려갈 값(공통+개별 합친 결과), 중앙 자신의 실제 값과 그 출처(중앙 지정 · portal.env · 기본값)",
