    "shrink": "줄일 필요가 없습니다.",
    "ifDeleted": "실행 중에는 중앙이 메모리에 읽어 둔 값을 계속 쓰므로 바로 바뀌지 않습니다. 파일이 없는 채로 중앙을 다시 시작하면 중앙이 지정한 주기가 모두 사라져, 엣지는 다음 설정 수신 때 지정값을 버리고 자기 ‘portal.env’ 값이나 기본값(장비 수집 1시간 등)으로 돌아가고 중앙 자신도 기본값을 씁니다. 파일이 깨져 읽히지 않으면 원본을 ‘.corrupt.<시각>’ 으로 보존하고, 중앙은 주기 부분을 빼고 ‘읽지 못했다’ 고 알려(구버전 엣지에는 503) 엣지가 직전 주기를 유지하게 합니다 — 관리자가 다시 저장하거나 특수 기능 › 다빈치 서비스 점검의 설정 파일 항목에서 기본값으로 확정하면 풀립니다. 설정 › 포탈 백업에 포함되므로 백업에서 복원할 수 있습니다.",
