      "보관 기간을 줄이면 다음 정리에서 오래된 로그가 지워지며 되돌릴 수 없습니다. 로그인 실패 분석·구성 변경 이력은 남은 로그만큼만 볼 수 있습니다.",
      "자격증명은 들어 있지 않습니다. 포탈 백업('설정 › 포탈 백업')에 포함됩니다."
