    "summary": "여러 vCenter 를 화면에 나열할 때 쓸 순서를 담은 작은 설정 파일입니다. 화면 곳곳의 vCenter 선택 목록과 vCenter 관리 목록이 이 순서대로 정렬됩니다. 관리자가 순서를 저장한 포탈에만 생기며, 파일이 없으면 기본 순서를 씁니다.",
    "stores": [
      "‘order’: vCenter id(등록 번호)를 원하는 순서대로 나열한 목록 하나뿐입니다. 저장할 때 중복과 빈 값은 빼고 저장합니다.",
      "목록에 없는 vCenter(나중에 새로 등록한 것 등)는 정렬된 목록 뒤에 원래 순서대로 붙습니다. 목록에 있지만 지금 등록되어 있지 않은 id 는 아무 영향이 없습니다."
    ],
    "writer": "관리자가 '설정 › vCenter 관리 › vCenter 등록·관리' 페이지 아래의 'vCenter 표시 순서' 에서 위·아래로 옮기고 '순서 저장' 을 누를 때만 씁니다. 주기적으로 쓰는 일은 없습니다. 저장은 관리자이면서 모든 vCenter 를 볼 수 있는(전체 범위) 계정만 할 수 있고, 목록을 비우는 저장은 명시적인 초기화 요청일 때만 받습니다(조회에 실패한 화면이 실수로 순서를 지우지 않게). 저장하면 감사 로그에 'vCenter 순서 변경' 이 남습니다.",
